using Oikonomis.Application;using Oikonomis.Camt;using Oikonomis.Domain;using Oikonomis.Infrastructure;using Microsoft.EntityFrameworkCore;
var b=Host.CreateApplicationBuilder(args);b.Services.AddInfrastructure(b.Configuration);b.Services.AddSingleton<ITransactionSourceImporter,CamtImporter>();b.Services.AddScoped<JobStore>();b.Services.AddHostedService<ImportWorker>();await b.Build().RunAsync();
sealed class ImportWorker(IServiceScopeFactory scopes,ILogger<ImportWorker> log):BackgroundService{readonly string worker=Environment.GetEnvironmentVariable("WORKER_ID")??$"{Environment.MachineName}-{Guid.NewGuid():n}";protected override async Task ExecuteAsync(CancellationToken ct){while(!ct.IsCancellationRequested){try{using var scope=scopes.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AppDbContext>();await db.Database.EnsureCreatedAsync(ct);var job=await scope.ServiceProvider.GetRequiredService<JobStore>().ClaimAsync(worker,TimeSpan.FromMinutes(15),ct);if(job is null){await Task.Delay(1000,ct);continue;}using(log.BeginScope(new Dictionary<string,object>{{"ImportJobId",job.Id},{"WorkerId",worker}}))await Process(job,scope,ct);}catch(OperationCanceledException)when(ct.IsCancellationRequested){}catch(Exception ex){log.LogError(ex,"Worker loop failed");await Task.Delay(2000,ct);}}}async Task Process(ImportJob job,IServiceScope scope,CancellationToken ct){var db=scope.ServiceProvider.GetRequiredService<AppDbContext>();try{var createdTransactions=new List<BankTransaction>();await using var stream=await scope.ServiceProvider.GetRequiredService<IObjectStorage>().OpenReadAsync(job.ImportFile.ObjectStorageKey,ct);var result=await scope.ServiceProvider.GetRequiredService<ITransactionSourceImporter>().ImportAsync(new(job.Id,job.ImportFile.OriginalFileName),stream,ct);await using var tx=await db.Database.BeginTransactionAsync(ct);foreach(var ps in result.Statements){var iban=Normalization.Iban(ps.Account.Iban);var account=await db.BankAccounts.FirstOrDefaultAsync(x=>x.Iban==iban,ct);if(account is null){account=new(){Iban=iban,OtherIdentification=ps.Account.OtherId,Currency=ps.Account.Currency,AccountName=ps.Account.Name,ServicerBic=ps.Account.Bic};db.Add(account);await db.SaveChangesAsync(ct);}var statement=await db.BankStatements.FirstOrDefaultAsync(x=>x.BankAccountId==account.Id&&x.StatementId==ps.StatementId,ct);if(statement is null){statement=new(){ImportJobId=job.Id,BankAccountId=account.Id,MessageId=ps.MessageId,StatementId=ps.StatementId,CreatedDateTimeUtc=ps.CreatedAt,FromDateTimeUtc=ps.From,ToDateTimeUtc=ps.To,OpeningBookedBalance=ps.Opening,ClosingBookedBalance=ps.Closing,Currency=ps.Account.Currency,RawStatementJson=ps.RawJson};db.Add(statement);await db.SaveChangesAsync(ct);}foreach(var p in ps.Transactions){var fp=Normalization.Fingerprint(account.Id,p);if(await db.BankTransactions.AnyAsync(x=>x.Fingerprint==fp,ct))continue;var newTransaction=new BankTransaction{BankStatementId=statement.Id,BankAccountId=account.Id,EntryReference=p.EntryRef,AccountServicerReference=p.ServicerRef,InstructionId=p.InstructionId,EndToEndId=p.EndToEndId,MandateId=p.MandateId,TransactionId=p.TransactionId,BookingDate=p.BookingDate,ValueDate=p.ValueDate,Amount=p.Amount,Currency=p.Currency,CreditDebitIndicator=p.Indicator,Status=p.Status,BankTransactionCode=p.BankCode,ProprietaryTransactionCode=p.ProprietaryCode,CounterpartyName=p.CounterpartyName,CounterpartyIban=p.CounterpartyIban,CounterpartyBic=p.CounterpartyBic,RemittanceInformation=p.Remittance,AdditionalInformation=p.AdditionalInfo,Fingerprint=fp,RawEntryJson=p.RawJson};db.Add(newTransaction);createdTransactions.Add(newTransaction);}}var categoryRules=await db.CounterpartyCategoryRules.AsNoTracking().ToDictionaryAsync(x=>x.CounterpartyIban,ct);foreach(var transaction in createdTransactions){var iban=Normalization.Iban(transaction.CounterpartyIban);if(iban is not null&&categoryRules.TryGetValue(iban,out var rule))db.Add(new TransactionLabel{BankTransactionId=transaction.Id,Category=rule.Category,Subcategory=rule.Subcategory,Source=CategorySource.IbanRule});else{var match=TransactionCategorizer.Classify(transaction.CounterpartyName,transaction.RemittanceInformation,transaction.BankTransactionCode,transaction.CreditDebitIndicator==CreditDebitIndicator.Credit);db.Add(new TransactionLabel{BankTransactionId=transaction.Id,Category=match.Category,Subcategory=match.Subcategory,Source=CategorySource.Automatic});}}foreach(var w in result.Warnings)db.Add(new ImportWarning{ImportJobId=job.Id,StatementId=w.StatementId,EntryReference=w.EntryReference,Code=w.Code,Message=w.Message,XmlPath=w.XmlPath});job.Status=result.Warnings.Count>0?ImportStatus.CompletedWithWarnings:ImportStatus.Completed;job.CompletedAtUtc=DateTimeOffset.UtcNow;await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);log.LogInformation("Import completed");}catch(Exception ex){job.Status=ImportStatus.Failed;job.CompletedAtUtc=DateTimeOffset.UtcNow;job.ErrorCode=ex is InvalidDataException?"INVALID_CAMT":"PROCESSING_ERROR";job.ErrorMessage=ex.Message.Length>1000?ex.Message[..1000]:ex.Message;await db.SaveChangesAsync(ct);log.LogWarning(ex,"Import failed");}}}
